// Generates TypeScript types and a schema module from the language-neutral
// JSON Schema contracts in packages/kernel-api/schemas (architecture AP-6).
//
//   node scripts/gen-schema-types.ts          regenerate
//   node scripts/gen-schema-types.ts --check  fail if the generated files are stale

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { basename, join, resolve } from 'node:path'
import { compile } from 'json-schema-to-typescript'

const root = resolve(import.meta.dirname, '..')
const schemaDir = join(root, 'packages/kernel-api/schemas')
const outDir = join(root, 'packages/kernel-api/src/generated')
const check = process.argv.includes('--check')

const banner = (source: string) =>
  `// Generated by scripts/gen-schema-types.ts from packages/kernel-api/schemas/${source}.\n// Do not edit by hand; run \`yarn gen:schemas\`.\n`

function camel(name: string): string {
  return name.replace(/[-.](\w)/g, (_, c: string) => c.toUpperCase())
}

const outputs = new Map<string, string>()
for (const file of readdirSync(schemaDir).filter((name) => name.endsWith('.schema.json')).sort()) {
  const stem = basename(file, '.schema.json')
  const schema = JSON.parse(readFileSync(join(schemaDir, file), 'utf8'))

  // Compile every definition, not only those reachable from the (type-less) root.
  const wrapper = { ...schema, title: '__Root', type: 'object', additionalProperties: false }
  let types = await compile(wrapper, '__Root', {
    bannerComment: '',
    unreachableDefinitions: true,
    additionalProperties: false,
    strictIndexSignatures: true,
    style: { singleQuote: true, semi: false, printWidth: 120 },
  })
  types = types.replace(/^(\/\*\*(?:(?!\*\/)[\s\S])*\*\/\n)?export interface __Root \{\}\n*/m, '')
  // Drop the generator's boilerplate about the synthetic root.
  types = types.replace(/^ \*\n \* This interface was referenced by `__Root`'s JSON-Schema\n \* via the `definition` "\w+"\.\n/gm, '')
  types = types.replace(/^\/\*\*\n \* This interface was referenced by `__Root`'s JSON-Schema\n \* via the `definition` "\w+"\.\n \*\/\n/gm, '')

  outputs.set(`${stem}.types.ts`, `${banner(file)}\n${types.trim()}\n`)
  outputs.set(
    `${stem}.schema.ts`,
    `${banner(file)}\nexport const ${camel(stem)}Schema = ${JSON.stringify(schema, null, 2)} as const\n`,
  )
}

const stale: string[] = []
for (const [name, content] of outputs) {
  const path = join(outDir, name)
  const current = existsSync(path) ? readFileSync(path, 'utf8') : undefined
  if (current === content) continue
  if (check) stale.push(name)
  else writeFileSync(path, content)
}
for (const name of existsSync(outDir) ? readdirSync(outDir) : []) {
  if (!outputs.has(name)) stale.push(`${name} (no longer generated)`)
}

if (stale.length > 0) {
  console.error(`Generated schema files are out of date: ${stale.join(', ')}. Run \`yarn gen:schemas\`.`)
  process.exitCode = 1
} else if (check) {
  console.log(`Generated schema files are up to date (${outputs.size} files).`)
} else {
  console.log(`Generated ${outputs.size} files in packages/kernel-api/src/generated.`)
}
